      AND CONVERT(varbinary(max), DocumentJson) = CONVERT(varbinary(max), CAST(N'' AS nvarchar(max)) + N'{"id":"25a850f1-a02f-4a88-a202-84fa3342e28f","code":"login-api","name":"\u5206\u5E73\u53F0\u5355\u4F1A\u8BDD\u767B\u5F55\u63A5\u5165\u6307\u5357","description":"\u5206\u5E73\u53F0\u5355\u4F1A\u8BDD\u767B\u5F55\u63A5\u5165\u6307\u5357","status":0,"logicalRevision":5,"documents":[{"id":"0d64a23c-b69d-423e-8047-2e01f06eabdb","fileName":"backend-delivery-record-v2-agent-guide.md","mediaType":"text/markdown","sha256":"73a31730365b44a49d3683900bed0dcbc46b4e53867cad227ccf29f7ba6d42bf","content":"# RVM \u540E\u53F0\u6295\u9012\u8BB0\u5F55 V2 \u534F\u8BAE\u8FC1\u79FB\u4EFB\u52A1\u4E66\uFF08\u4F9B AI Agent \u6267\u884C\uFF09\n\n## 1. \u4EFB\u52A1\u76EE\u6807\n\n\u5C06\u540E\u53F0\u5F53\u524D\u7684\u6295\u9012\u8BB0\u5F55\u534F\u8BAE\u76F4\u63A5\u66FF\u6362\u4E3A\u7EDF\u4E00\u4E8B\u4EF6\u65F6\u95F4\u7EBF\u534F\u8BAE\uFF1A\n\n- \u4F7F\u7528\u5BA2\u6237\u7AEF\u7A33\u5B9A \u0060sessionId/eventId/itemId/beltReturnId\u0060\uFF1B\n- \u7528\u7EDF\u4E00\u6709\u5E8F \u0060events[]\u0060 \u66FF\u6362\u65E7 \u0060detailList\u0060\uFF1B\n- \u4E8B\u4EF6\u53EA\u5206\u4E3A \u0060ITEM_RESULT\u0060 \u548C \u0060ABNORMAL\u0060\uFF1B\n- \u670D\u52A1\u7AEF\u6839\u636E ITEM_RESULT \u8BA1\u7B97\u6570\u91CF\u548C\u603B\u9000\u6B3E\uFF0C\u4E0D\u518D\u63A5\u6536\u5BA2\u6237\u7AEF summary\uFF1B\n- \u56FE\u7247\u76F4\u63A5\u6309\u5BA2\u6237\u7AEF \u0060eventId\u0060 \u7ED1\u5B9A\uFF0C\u4E0D\u518D\u8FD4\u56DE\u670D\u52A1\u7AEF Detail UUID \u4F9B App \u4E8C\u6B21\u6620\u5C04\uFF1B\n- \u5143\u6570\u636E\u5199\u5165\u5FC5\u987B\u539F\u5B50\u5316\u3001\u53EF\u5E42\u7B49\u91CD\u653E\uFF1B\n- \u76F4\u63A5\u66FF\u6362\u73B0\u6709\u63A5\u53E3\uFF0C\u4E0D\u5B9E\u73B0\u65B0\u65E7\u8BF7\u6C42\u517C\u5BB9\u5165\u53E3\u3002\n\n\u672C\u4EFB\u52A1\u53EA\u4FEE\u6539\u540E\u53F0\u4ED3\u5E93\u3002\u4E0D\u8981\u4FEE\u6539 Android \u4ED3\u5E93\uFF0C\u4E5F\u4E0D\u8981\u81EA\u884C\u6539\u53D8\u672C\u6587\u4E1A\u52A1\u679A\u4E3E\u548C\u5B57\u6BB5\u8BED\u4E49\u3002\n\n---\n\n## 2. Agent \u5F00\u59CB\u5DE5\u4F5C\u524D\u5FC5\u987' + N'B\u6267\u884C\n\n1. \u9605\u8BFB\u540E\u53F0\u4ED3\u5E93\u7684 \u0060AGENTS.md\u0060\u3001\u0060CLAUDE.md\u0060\u3001README\u3001\u8FC1\u79FB\u89C4\u8303\u548C\u6D4B\u8BD5\u89C4\u8303\u3002\n2. \u5B9A\u4F4D\u4EE5\u4E0B\u73B0\u6709\u5B9E\u73B0\uFF1A\n   - \u0060POST /api/EmEquipment/SyncDeliveryRecord\u0060\uFF1B\n   - \u0060POST /api/EmEquipment/UploadDeliveryRecordImage/{recordId}\u0060\uFF1B\n   - \u6295\u9012\u8BF7\u6C42 DTO\u3001Controller\u3001Service\u3001Repository\u3001ORM Entity\uFF1B\n   - Delivery/Detail \u6570\u636E\u8868\u53CA\u6570\u636E\u5E93 migration\uFF1B\n   - \u56FE\u7247\u5B58\u50A8\u3001\u8BBE\u5907\u9274\u6743\u548C \u0060ApiEnvelope\u0060 \u5B9E\u73B0\uFF1B\n   - \u6295\u9012\u8BB0\u5F55\u67E5\u8BE2\u3001\u62A5\u8868\u3001\u9000\u6B3E\u3001\u7528\u6237\u5386\u53F2\u7B49\u4E0B\u6E38\u8BFB\u6A21\u578B\uFF1B\n   - \u5F53\u524D\u63A5\u53E3\u53CA\u56FE\u7247\u63A5\u53E3\u6D4B\u8BD5\u3002\n3. \u5148\u8BB0\u5F55\u65E7\u8C03\u7528\u94FE\u548C\u53D7\u5F71\u54CD\u6587\u4EF6\uFF0C\u518D\u5B9E\u65BD\u4FEE\u6539\u3002\n4. \u4E0D\u5F97\u56E0\u672C\u6587\u6CA1\u6709\u63D0\u4F9B\u540E\u53F0\u6587\u4EF6\u8DEF\u5F84\u800C\u731C\u6D4B\u76EE\u5F55\uFF1B\u5FC5\u987B\u6839\u636E\u5B9E\u9645\u4ED3\u5E93\u5B9A\u4F4D\u3002\n5. \u4E0D\u5F97\u5220\u9664\u5386\u53F2\u6295\u9012\u6570\u636E\u3002\u82E5\u73B0\u6709\u6570\u636E\u65E0\u6CD5\u65E0\u635F\u8F6C\u6362\uFF0C\u4FDD\u7559\u65E7\u6570\u636E\u53EA\u8BFB\u67E5\u8BE2\u80FD\u529B\uFF0C\u4E0D\u5F97\u4F2A\u9020 V2 \u5BA2\u6237\u7AEF ID \u6216\u4E8B\u4EF6\u987A\u5E8F\u3002\n6. \u672A\u83B7\u4ED3\u5E93\u6240\u6709\u8005\u6388\u6743\u4E0D\u8981\u63D0\u4EA4\u4EE3\u7801\u3002\n\n---\n\n## 3. \u5F53\u524D\u65E7\u534F\u8BAE\uFF08\u9700\u8981\u66FF\u6362\uFF09\n\nAndroid \u5F53\u524D\u8C03\u7528\uFF1A\n\n\u0060\u0060\u0060text\nPOST /api/EmEquipment/SyncDeliveryRecord\n\u0060\u0060\u0060\n\n\u65E7\u8BF7\u6C42\u5927\u81F4\u4E3A\uFF1A\n\n\u0060\u0060\u0060text\nDeliveryRecord\n\u251C\u2500 id                  // App \u672C\u5730 R' + N'oom \u81EA\u589E ID\uFF0C\u4E0D\u662F\u4E1A\u52A1 ID\n\u251C\u2500 deliveryCount\n\u251C\u2500 deliveryEndTime\n\u251C\u2500 deliveryTime\n\u251C\u2500 detailList\n\u2502  \u2514\u2500 Detail\n\u2502     \u251C\u2500 andDeliveryId\n\u2502     \u251C\u2500 barCode\n\u2502     \u251C\u2500 deliveryTime\n\u2502     \u251C\u2500 deliveryType\n\u2502     \u251C\u2500 imgUrl\n\u2502     \u251C\u2500 refundAmount\n\u2502     \u2514\u2500 rejectReason\n\u251C\u2500 deviceNo\n\u251C\u2500 refundType\n\u251C\u2500 rejectRetryCount\n\u2514\u2500 userId\n\u0060\u0060\u0060\n\n\u65E7\u54CD\u5E94\u4E3A\u670D\u52A1\u7AEF\u660E\u7EC6 ID \u6620\u5C04\uFF1A\n\n\u0060\u0060\u0060text\nList\u003CDeliveryResult\u003E\n\u251C\u2500 id                  // \u670D\u52A1\u7AEF record/detail UUID\n\u251C\u2500 andDeliveryId       // App \u672C\u5730\u660E\u7EC6 ID\n\u2514\u2500 imgUrl\n\u0060\u0060\u0060\n\n\u65E7\u56FE\u7247\u63A5\u53E3\uFF1A\n\n\u0060\u0060\u0060text\nPOST /api/EmEquipment/UploadDeliveryRecordImage/{recordId}\n\u0060\u0060\u0060\n\n\u5176\u4E2D \u0060recordId\u0060 \u662F\u5143\u6570\u636E\u63A5\u53E3\u8FD4\u56DE\u7684\u670D\u52A1\u7AEF UUID\u3002V2 \u5FC5\u987B\u5220\u9664\u8FD9\u79CD\u5BA2\u6237\u7AEF\u672C\u5730\u660E\u7EC6 ID \u2192 \u670D\u52A1\u7AEF Detail UUID \u7684\u4E8C\u6B21\u6620\u5C04\u3002\n\n---\n\n## 4. \u76EE\u6807\u63A5\u53E3\n\n### 4.1 \u6295\u9012\u5143\u6570\u636E\n\n\u76F4\u63A5\u66FF\u6362\u73B0\u6709\u63A5\u53E3\uFF1A\n\n\u0060\u0060\u0060text\nPOST /api/EmEquipment/SyncDeliveryRecord\nContent-Type: application/json\nAuthorization: \u6CBF\u7528\u73B0\u6709\u8BBE\u5907\u9274\u6743\n\u0060\u0060\u0060\n\n\u4E0D\u518D\u63A5\u53D7\u65E7 \u0060detailList\u0060 \u8BF7\u6C42\u3002\n\n### 4.2 \u4E8B\u4EF6\u56FE\u7247\n\nURL \u4F4D\u7F6E\u4FDD\u6301\u4E0D\u53D8\uFF0C\u4F46\u8DEF\u5F84\u53C2\u6570\u8BED\u4E49\u6539\u53D8\uFF1A\n\n\u0060\u0060\u0060text\nPOST /api/EmEquipment/UploadDeliveryRecordImage/{eventId}\nContent-Type: multipart/form-data\nAuthorization:' + N' \u6CBF\u7528\u73B0\u6709\u8BBE\u5907\u9274\u6743\n\u0060\u0060\u0060\n\n- \u0060{eventId}\u0060 \u662F App \u521B\u5EFA\u5E76\u5728\u5143\u6570\u636E\u4E2D\u63D0\u4EA4\u7684\u4E8B\u4EF6 UUID\uFF1B\n- \u4E0D\u518D\u662F\u670D\u52A1\u7AEF\u751F\u6210\u7684 Delivery/Detail UUID\uFF1B\n- multipart \u5FC5\u987B\u5305\u542B\u56FE\u7247 \u0060file\u0060\uFF1B\n- \u65E7 \u0060filePath\u0060 \u662F\u5426\u4E3A\u5E95\u5C42\u6587\u4EF6\u5B58\u50A8\u57FA\u7840\u8BBE\u65BD\u6240\u5FC5\u9700\uFF0CAgent \u5FC5\u987B\u68C0\u67E5\u5B9E\u9645\u5B9E\u73B0\uFF1A\n  - \u82E5\u4EC5\u7528\u4E8E\u65E7\u4E1A\u52A1\u5173\u8054\uFF0C\u5219\u5220\u9664\uFF1B\n  - \u82E5\u5BF9\u8C61\u5B58\u50A8\u7EC4\u4EF6\u4ECD\u9700\u8981\uFF0C\u5219\u53EF\u4FDD\u7559\u4E3A\u5185\u90E8\u517C\u5BB9\u5B57\u6BB5\uFF0C\u4F46\u4E0D\u5F97\u53C2\u4E0E\u4E8B\u4EF6\u5F52\u5C5E\u5224\u65AD\uFF0C\u5E76\u5FC5\u987B\u5199\u5165 OpenAPI\u3002\n\n---\n\n## 5. V2 \u5143\u6570\u636E\u8BF7\u6C42 Schema\n\n\u0060\u0060\u0060text\nDeliverySessionUploadRequest\n\u251C\u2500 sessionId                    UUID\uFF0C\u8BA4\u8BC1\u8BBE\u5907\u8303\u56F4\u5185\u552F\u4E00\n\u251C\u2500 startedAt                   RFC 3339 UTC \u65F6\u95F4\n\u251C\u2500 endedAt                     RFC 3339 UTC \u65F6\u95F4\uFF0C\u4E0D\u65E9\u4E8E startedAt\n\u251C\u2500 refundType                  \u6574\u6570 1..5\n\u251C\u2500 userId?                     refundType=2 \u65F6\u5FC5\u586B\uFF1B\u5176\u4ED6\u65B9\u5F0F\u7701\u7565\n\u2514\u2500 events: List\u003CDeliveryEvent\u003E \u975E\u7A7A\uFF0C\u6309 eventSequence \u5347\u5E8F\n\u0060\u0060\u0060\n\n### 5.1 refundType\n\n\u6CBF\u7528\u5F53\u524D\u4E1A\u52A1\u503C\uFF1A\n\n\u0060\u0060\u0060text\n1 = RECEIPT   \u5C0F\u7968\u8FD4\u5229\n2 = ACCOUNT   \u8D26\u53F7\u8FD4\u5229\n3 = QR_CODE   \u4E8C\u7EF4\u7801\u8FD4\u5229\n4 = OCTOPUS   \u516B\u8FBE\u901A\u8FD4\u5229\n5 = DONATION  \u6350\u8D60\u8FD4\u5229\n\u0060\u0060\u0060\n\n\u89C4\u5219\uFF1A\n\n- \u0060refundType=2\u0060\uFF1A\u0060userId\u0060 \' + N'u5FC5\u987B\u5B58\u5728\u4E14\u975E\u7A7A\uFF1B\n- \u0060refundType!=2\u0060\uFF1A\u8BF7\u6C42\u4E0D\u5F97\u643A\u5E26 \u0060userId\u0060\uFF1B\n- \u0060deviceNo\u0060 \u4E0D\u518D\u7531\u8BF7\u6C42\u4F53\u63D0\u4F9B\uFF1B\u8BBE\u5907\u8EAB\u4EFD\u5FC5\u987B\u4ECE\u5F53\u524D\u8BA4\u8BC1 token/context \u83B7\u53D6\uFF0C\u9632\u6B62\u8BF7\u6C42\u4F53\u4F2A\u9020\u8BBE\u5907\u5F52\u5C5E\u3002\n\n### 5.2 DeliveryEvent\n\n\u0060\u0060\u0060text\nDeliveryEvent\n\u251C\u2500 eventId          UUID\uFF0C\u5168\u5C40\u552F\u4E00\uFF1B\u540C\u65F6\u4F5C\u4E3A\u5E42\u7B49\u952E\u548C\u56FE\u7247\u7ED1\u5B9A\u952E\n\u251C\u2500 eventSequence    \u6B63\u6574\u6570\uFF1B\u540C\u4E00 session \u5185\u552F\u4E00\u4E14\u9012\u589E\n\u251C\u2500 occurredAt       RFC 3339 UTC \u65F6\u95F4\n\u251C\u2500 eventType        ITEM_RESULT / ABNORMAL\n\u2514\u2500 data             \u53EA\u80FD\u5339\u914D eventType \u5BF9\u5E94\u7ED3\u6784\n\u0060\u0060\u0060\n\n\u8981\u6C42\uFF1A\n\n- \u0060events\u0060 \u6570\u7EC4\u6309 \u0060eventSequence\u0060 \u5347\u5E8F\uFF1B\n- \u4E0D\u8981\u6C42 eventSequence \u8FDE\u7EED\u65E0\u7F3A\u53E3\uFF1B\n- \u0060occurredAt\u0060 \u7528\u4E8E\u4E1A\u52A1\u5BA1\u8BA1\uFF0C\u4E0D\u80FD\u66FF\u4EE3 eventSequence \u6392\u5E8F\uFF1B\n- eventType \u672A\u77E5\u6216 data \u7ED3\u6784\u4E0D\u5339\u914D\u65F6\u62D2\u7EDD\u6574\u4E2A\u8BF7\u6C42\uFF1B\n- \u4E0D\u5141\u8BB8\u90E8\u5206\u4E8B\u4EF6\u6210\u529F\u3002\n\n---\n\n## 6. ITEM_RESULT\n\n\u0060\u0060\u0060text\nItemResultData\n\u251C\u2500 itemId              UUID\uFF0C\u540C\u4E00 session \u5185\u552F\u4E00\n\u251C\u2500 barcode?            \u53EF\u9009\uFF1B\u5B58\u5728\u65F6\u5FC5\u987B\u4E3A\u975E\u7A7A\u5B57\u7B26\u4E32\n\u251C\u2500 itemResult          ACCEPTED / REJECTED / INTERRUPTED\n\u251C\u2500 reasonCode?         \u6761\u4EF6\u5FC5\u586B\uFF0C\u89C1\u4E0B\u6587\n\u251C\u2500 refundAmount        \u89C4\u8303\u5316\u975E\u8D1F\u5341\u8FDB\u5236\u5B57\u7B26\u4E32\n\u251C\u2500 imageAvailability   NONE / ' + N'AVAILABLE / MISSING\n\u251C\u2500 beltReturnId?       UUID\uFF0C\u540C\u4E00 session \u5185\u552F\u4E00\u7684\u9000\u56DE\u5173\u8054\n\u2514\u2500 beltReturnResult?   CLEARED / COMMAND_FAILED / CLEARANCE_UNCONFIRMED\n\u0060\u0060\u0060\n\n### 6.1 ItemResult \u6761\u4EF6\u89C4\u5219\n\n| itemResult | reasonCode | refundAmount |\n|---|---|---|\n| ACCEPTED | \u5FC5\u987B\u7701\u7565 | \u975E\u8D1F\u7CBE\u786E\u5341\u8FDB\u5236\u5B57\u7B26\u4E32 |\n| REJECTED | \u5FC5\u586B\u4E14\u5C5E\u4E8E\u62D2\u6536\u539F\u56E0\u96C6\u5408 | \u56FA\u5B9A\u4E3A \u0060\u00220\u0022\u0060 |\n| INTERRUPTED | \u5FC5\u586B\u4E14\u5C5E\u4E8E\u4E2D\u65AD\u539F\u56E0\u96C6\u5408 | \u56FA\u5B9A\u4E3A \u0060\u00220\u0022\u0060 |\n\n\u91D1\u989D\u89C4\u5219\uFF1A\n\n- \u7981\u6B62\u4F7F\u7528\u4E8C\u8FDB\u5236\u6D6E\u70B9\u53C2\u4E0E\u8BA1\u7B97\uFF1B\u540E\u53F0\u4F7F\u7528 Decimal/BigDecimal \u6216\u6570\u636E\u5E93\u7CBE\u786E decimal\uFF1B\n- JSON \u4E2D\u91D1\u989D\u4E3A\u5B57\u7B26\u4E32\uFF1B\n- \u7981\u6B62\u79D1\u5B66\u8BA1\u6570\u6CD5\u3001\u8D1F\u6570\u3001NaN\u3001Infinity\u3001\u524D\u5BFC\u6B63\u53F7\u548C\u9690\u5F0F\u820D\u5165\uFF1B\n- \u6570\u503C\u96F6\u7EDF\u4E00\u4E3A \u0060\u00220\u0022\u0060\uFF1B\n- \u603B\u9000\u6B3E\u7531\u540E\u53F0\u5BF9\u5168\u90E8 \u0060ACCEPTED.refundAmount\u0060 \u7CBE\u786E\u6C42\u548C\uFF1B\n- \u91D1\u989D\u7CBE\u5EA6\u548C\u4E0A\u9650\u4F18\u5148\u590D\u7528\u540E\u53F0\u5DF2\u6709\u9000\u6B3E\u9886\u57DF\u7EA6\u675F\uFF1B\u82E5\u5F53\u524D\u6CA1\u6709\u660E\u786E\u7EA6\u675F\uFF0CAgent \u5FC5\u987B\u5728\u5B9E\u73B0\u62A5\u544A\u4E2D\u8BF4\u660E\u6240\u9009 decimal \u7CBE\u5EA6\uFF0C\u4E0D\u5F97\u9759\u9ED8\u622A\u65AD\u3002\n\n### 6.2 REJECTED reasonCode\uFF08\u4FDD\u7559\u73B0\u6709\u4E0A\u4F20\u503C\uFF09\n\n\u4EE5\u4E0B\u503C\u7684\u5927\u5C0F\u5199\u548C\u62FC\u5199\u5FC5\u987B\u4FDD\u6301\uFF1A\n\n\u0060\u0060\u0060text\nunknown_barcode\nno_aiLabel\nunwanted_object\nsession_limit\nbin_full\nai_barcode_not_match\nai_label_not_match\ntoo' + N'_heavy\ntoo_light\nwrong_size\nwrong_material\nai_others\nai_low_confidence\nai_unknown\nabnormal\nmultiple_containers\n\u0060\u0060\u0060\n\n\u4E0D\u8981\u628A \u0060multiple_containers\u0060 \u66FF\u6362\u4E3A ABNORMAL \u679A\u4E3E\uFF1B\u7269\u6599\u62D2\u6536\u539F\u56E0\u4E0E\u5F02\u5E38\u4E8B\u4EF6\u662F\u4E24\u4E2A\u4E0D\u540C\u4E8B\u5B9E\u3002\n\n### 6.3 INTERRUPTED reasonCode\uFF08V2 \u65B0\u589E\uFF09\n\n\u0060\u0060\u0060text\naffected_by_belt_return\napp_process_restarted\nroute_completion_timeout\nroute_command_failed\nunexpected_belt_clear\nevent_owner_mismatch\nsession_finalized_with_active_items\n\u0060\u0060\u0060\n\n---\n\n## 7. ABNORMAL\n\n\u0060\u0060\u0060text\nAbnormalEventData\n\u251C\u2500 abnormalCode        \u5FC5\u586B\uFF0C\u5B8C\u6574\u53F6\u5B50\u5F02\u5E38\u4EE3\u7801\n\u251C\u2500 affectedItemIds     \u975E\u7A7A UUID \u6570\u7EC4\uFF0C\u53EA\u80FD\u5F15\u7528\u540C\u4E00\u8BF7\u6C42\u4E2D\u7684 itemId\n\u251C\u2500 imageAvailability   NONE / AVAILABLE / MISSING\n\u251C\u2500 beltReturnId?       \u5173\u8054\u6574\u5E26\u9000\u56DE\u65F6\u586B\u5199\n\u2514\u2500 beltReturnResult?   \u4EC5\u9000\u56DE\u552F\u4E00\u89E6\u53D1\u4E8B\u4EF6\u586B\u5199\n\u0060\u0060\u0060\n\n### 7.1 abnormalCode\n\n\u89C6\u89C9\u5F02\u5E38\uFF1A\n\n\u0060\u0060\u0060text\nHAND_DETECTED\nIRREGULAR_MOVEMENT\nIRREGULAR_DELIVERY\nMULTIPLE_DELIVERY_TWO\nMULTIPLE_DELIVERY_THREE_OR_MORE\nILLEGAL_DELIVERY_AFTER_MD\n\u0060\u0060\u0060\n\n\u72B6\u6001\u548C\u6D41\u7A0B\u5F02\u5E38\uFF1A\n\n\u0060\u0060\u0060text\nUNEXPECTED_BELT_CLEAR\nEVENT_OWNER_MISMATCH\nROUTE_COMPLETION_TIMEOUT\nSESSION_FINALIZED_WITH_ACTIVE_ITEMS\n\u0060\u0060\u0060\n\n\u786C\u4EF6\u4E0E\u6E05\u7A7A\u5F02\u5E38\uFF1A\n\n\u0060\u0060\u0060text\nROUTE_COMMAND_FAILED\nBELT_RETURN_COMMAND_FAILED\nBELT_RETURN_CLEARANCE_TIMEOUT\n\u0060\u0060\u0060\n\n\u4E0D\u8981\u65B0\u589E \u0060CHEAT_SIGNAL\u0060\uFF1A\u5F53\u524D \u0060ma=2\u0060 \u53EA\u66F4\u65B0 App \u6B3A\u8BC8\u8BA1\u6570\u5E76\u53EF\u80FD\' + N'u89E6\u53D1\u9759\u9ED8\u7ED3\u675F\uFF0C\u4E0D\u521B\u5EFA\u6295\u9012 ABNORMAL\u3002\n\n### 7.2 \u56FE\u7247\u89C4\u5219\n\n- \u89C6\u89C9\u5F02\u5E38\u5FC5\u987B\u4F7F\u7528 \u0060imageAvailability=AVAILABLE\u0060 \u6216 \u0060MISSING\u0060\uFF1B\n- \u72B6\u6001\u3001\u6D41\u7A0B\u548C\u786C\u4EF6\u5F02\u5E38\u5FC5\u987B\u4F7F\u7528 \u0060imageAvailability=NONE\u0060\uFF1B\n- \u0060AVAILABLE\u0060 \u8868\u793A App \u51BB\u7ED3\u5143\u6570\u636E\u65F6\u6587\u4EF6\u5DF2\u5B58\u5728\uFF0C\u56FE\u7247\u7A0D\u540E\u901A\u8FC7 eventId \u63A5\u53E3\u4E0A\u4F20\uFF1B\n- \u0060MISSING\u0060 \u8868\u793A\u6309\u8BBE\u8BA1\u5E94\u6709\u56FE\u7247\uFF0C\u4F46 App \u51BB\u7ED3\u524D\u6587\u4EF6\u5DF2\u7F3A\u5931\u6216\u635F\u574F\uFF0C\u4E0D\u4F1A\u521B\u5EFA\u56FE\u7247\u4EFB\u52A1\uFF1B\n- \u0060NONE\u0060 \u8868\u793A\u8BE5\u4E8B\u4EF6\u6309\u8BBE\u8BA1\u4E0D\u62E5\u6709\u56FE\u7247\uFF1B\n- \u670D\u52A1\u7AEF\u4E0D\u9700\u8981\u5728\u672C\u6B21\u6539\u9020\u4E2D\u5EFA\u8BBE PENDING/TIMED_OUT/\u8FDF\u5230\u9644\u4EF6\u72B6\u6001\u673A\u3002\n\n---\n\n## 8. BeltReturn \u5173\u8054\u89C4\u5219\n\n\u0060\u0060\u0060text\nBeltReturnResult\n\u251C\u2500 CLEARED                 // App \u6536\u5230 JNI mo=1 \u6216 mo=2\n\u251C\u2500 COMMAND_FAILED          // \u53CD\u8F6C\u547D\u4EE4\u6267\u884C\u7ED3\u679C\u5931\u8D25\n\u2514\u2500 CLEARANCE_UNCONFIRMED   // \u672A\u6536\u5230 MO \u6216\u8FDB\u7A0B\u91CD\u542F\u5BFC\u81F4\u6E05\u7A7A\u7ED3\u679C\u672A\u77E5\n\u0060\u0060\u0060\n\n\u5B8C\u6574\u6027\u7EA6\u675F\uFF1A\n\n1. \u4E0D\u53C2\u4E0E\u9000\u56DE\u7684\u4E8B\u4EF6\u4E0D\u5F97\u643A\u5E26 \u0060beltReturnId/beltReturnResult\u0060\uFF1B\n2. \u643A\u5E26 \u0060beltReturnResult\u0060 \u5FC5\u987B\u540C\u65F6\u643A\u5E26 \u0060beltReturnId\u0060\uFF1B\n3. \u540C\u4E00\u8BF7\u6C42\u4E2D\uFF0C\u6BCF\u4E2A\u88AB\u5F15\u7528\u7684 beltReturnId \u5FC5\u987B\u6070\u597D\u6709\u4E00\u4E2A\u4E8B\u4EF6\u643A\u5E26 beltReturnResult\uFF1B\n4. \u5176\u4ED6\u53D7\u5F71\u54CD ITEM_RESULT/ABN' + N'ORMAL \u53EA\u5F15\u7528\u540C\u4E00 beltReturnId\uFF0C\u4E0D\u91CD\u590D\u7ED3\u679C\uFF1B\n5. \u4E0D\u521B\u5EFA\u72EC\u7ACB RETURN_EVENT\uFF1B\n6. \u4E0D\u4E0A\u4F20\u672C\u5730 BeltReturn \u7684 startedAt\u3001endedAt\u3001\u786C\u4EF6 ACK \u6216\u5185\u90E8\u6267\u884C\u72B6\u6001\u3002\n\n### 8.1 MB \u65B0\u534F\u8BAE\n\n\u0060\u0060\u0060text\nmb=1 \u2192 IRREGULAR_DELIVERY\nmb=2 \u2192 MULTIPLE_DELIVERY_TWO\nmb=3 \u2192 MULTIPLE_DELIVERY_THREE_OR_MORE\nmb=4 \u2192 ILLEGAL_DELIVERY_AFTER_MD\n\u0060\u0060\u0060\n\n\u6240\u6709 mb \u5F02\u5E38\u90FD\u89E6\u53D1\u6574\u5E26\u9000\u56DE\u3002\n\nMB=4 \u7279\u6B8A\u89C4\u5219\uFF1A\n\n- affectedItemIds \u5305\u542B\u6700\u8FD1\u4E00\u6B21 MD \u7684\u5DF2\u63A5\u6536\u7269\u6599\uFF0C\u4EE5\u53CA\u5F53\u65F6\u5176\u4ED6\u6D3B\u8DC3\u7269\u6599\uFF1B\n- \u6700\u8FD1 MD \u7269\u6599\u4ECD\u4FDD\u6301 \u0060itemResult=ACCEPTED\u0060\uFF0C\u9000\u6B3E\u91D1\u989D\u4E0D\u53D8\uFF1B\n- \u6700\u8FD1 MD ITEM_RESULT \u5F15\u7528\u8BE5 beltReturnId\uFF0C\u4F46\u4E0D\u643A\u5E26 beltReturnResult\uFF1B\n- \u0060ILLEGAL_DELIVERY_AFTER_MD\u0060 ABNORMAL \u662F\u9000\u56DE\u552F\u4E00\u89E6\u53D1\u6E90\uFF0C\u643A\u5E26 beltReturnResult\uFF1B\n- \u5176\u4ED6\u672A\u5B8C\u6210\u7269\u6599\u6309\u6574\u5E26\u9000\u56DE\u89C4\u5219\u7ED3\u6E05\uFF1B\n- MB=4 \u643A\u5E26\u89C6\u89C9\u8BC1\u636E\u56FE\u7247\u3002\n\n---\n\n## 9. \u8BF7\u6C42\u7EA7\u5B8C\u6574\u6027\u6821\u9A8C\n\n\u540E\u53F0\u5FC5\u987B\u5728\u5F00\u542F\u5199\u4E8B\u52A1\u524D\u5B8C\u6210\u7ED3\u6784\u6821\u9A8C\uFF0C\u5E76\u5728\u540C\u4E00\u4E8B\u52A1\u4E2D\u5B8C\u6210\u5173\u7CFB\u6821\u9A8C\u548C\u5199\u5165\u3002\u81F3\u5C11\u68C0\u67E5\uFF1A\n\n1. sessionId\u3001eventId\u3001itemId\u3001beltReturnId \u662F\u5408\u6CD5 UUID\uFF1B\n2. refundType \u53EA\u80FD\u4E3A 1..5\uFF1B\n3. ACCOUNT \u7684 userId \u975E\u7A7A\uFF0C\u5176\u4ED6 refundType \u4E0D\u643A\u5E26 userId\uFF1B\n4. startedAt/endedAt/occurredAt \u662F\u5408\u6CD5 RFC 3339 UTC \u65F6\u95F4\uFF1B\n5. en' + N'dedAt \u4E0D\u65E9\u4E8E startedAt\uFF1B\n6. events \u975E\u7A7A\uFF0CeventSequence \u4E3A\u6B63\u6574\u6570\u3001\u552F\u4E00\u3001\u9012\u589E\uFF1B\n7. \u6BCF\u4E2A itemId \u6070\u597D\u4E00\u4E2A ITEM_RESULT\uFF1B\n8. eventType \u4E0E data DTO \u4E25\u683C\u5339\u914D\uFF1B\n9. ACCEPTED/REJECTED/INTERRUPTED \u7684 reasonCode \u548C\u91D1\u989D\u6EE1\u8DB3\u6761\u4EF6\u77E9\u9635\uFF1B\n10. reasonCode \u548C abnormalCode \u5FC5\u987B\u5C5E\u4E8E\u672C\u6587\u96C6\u5408\uFF1B\n11. affectedItemIds \u975E\u7A7A\u3001\u65E0\u91CD\u590D\uFF0C\u5E76\u4E14\u5168\u90E8\u5F15\u7528\u672C\u8BF7\u6C42\u4E2D\u7684 itemId\uFF1B\n12. \u89C6\u89C9 abnormal \u7684 imageAvailability \u4E0D\u80FD\u4E3A NONE\uFF1B\u975E\u89C6\u89C9 abnormal \u5FC5\u987B\u4E3A NONE\uFF1B\n13. beltReturnId/result \u6EE1\u8DB3\u552F\u4E00\u89E6\u53D1\u6E90\u7EA6\u675F\uFF1B\n14. MB=4 \u81F3\u5C11\u5173\u8054\u4E00\u4E2A ACCEPTED item\uFF0C\u5E76\u4E14\u8BE5 item \u5F15\u7528\u540C\u4E00 beltReturnId\uFF1B\n15. \u540C\u4E00 eventId \u53EA\u80FD\u6709\u4E00\u4E2A imageAvailability \u548C\u6700\u591A\u4E00\u4E2A\u56FE\u7247\u9644\u4EF6\u3002\n\n\u4EFB\u4F55\u5931\u8D25\u90FD\u62D2\u7EDD\u6574\u4E2A\u8BF7\u6C42\uFF0C\u4E0D\u5141\u8BB8\u5199\u5165\u534A\u4E2A session\u3002\n\n---\n\n## 10. \u670D\u52A1\u7AEF\u6D3E\u751F\u6570\u636E\n\nV2 \u8BF7\u6C42\u4E0D\u518D\u4E0A\u4F20\uFF1A\n\n\u0060\u0060\u0060text\ndeliveryCount\nrejectRetryCount\nsummary\ntotalRefundAmount\n\u0060\u0060\u0060\n\n\u540E\u53F0\u4ECE ITEM_RESULT \u539F\u5B50\u8BA1\u7B97\uFF1A\n\n\u0060\u0060\u0060text\nacceptedCount    = itemResult == ACCEPTED \u7684\u6570\u91CF\nrejectedCount    = itemResult == REJECTED \u7684\u6570\u91CF\ninterruptedCount = itemResult == INTERRUPTED \u7684\u6570\u91CF\ntotalRefundAmount = ACCEPTED.refundAmount \u7684\u7CBE\u786E\u5341\u8FDB\u5236\u548C\n\u0060\u0060\u0060\n\n\u540E\u53F0\u53EF\u4EE5\u5B58\u50A8\u8FD9\u4E9B\u6D3E\u751F\u5217\u7528\u4E8E\u67E5\u8BE2\u6027\u80FD\uFF0C\u4F46\u5B83\u4EEC\u5FC5\u987B\u75' + N'31\u540C\u4E00\u4E8B\u52A1\u5185\u7684 events \u8BA1\u7B97\uFF0C\u4E0D\u80FD\u63A5\u53D7\u5BA2\u6237\u7AEF\u8986\u76D6\u3002\n\n\u65E7\u5B57\u6BB5\u6620\u5C04\uFF1A\n\n| \u65E7\u5B57\u6BB5 | V2 \u6765\u6E90/\u5904\u7406 |\n|---|---|\n| id | \u5220\u9664\uFF1B\u4E0D\u5F97\u628A App \u672C\u5730 Room \u81EA\u589E ID \u4F5C\u4E3A\u4E1A\u52A1\u4E3B\u952E |\n| deliveryTime | startedAt |\n| deliveryEndTime | endedAt |\n| deliveryCount | \u670D\u52A1\u7AEF\u4ECE ITEM_RESULT \u63A8\u5BFC |\n| rejectRetryCount | \u670D\u52A1\u7AEF\u4ECE ITEM_RESULT \u63A8\u5BFC\uFF1B\u4E0D\u8981\u7EE7\u7EED\u6DF7\u5408 REJECTED/INTERRUPTED |\n| detailList | \u5B8C\u5168\u66FF\u6362\u4E3A events |\n| deviceNo | \u4ECE\u8BBE\u5907\u9274\u6743\u4E0A\u4E0B\u6587\u83B7\u53D6 |\n| refundType | \u4FDD\u7559 |\n| userId | ACCOUNT \u5FC5\u586B\uFF0C\u5176\u4ED6\u7701\u7565 |\n| Detail.andDeliveryId | \u5220\u9664\uFF1B\u4F7F\u7528 itemId/eventId |\n| Detail.barCode | ItemResultData.barcode |\n| Detail.deliveryTime | DeliveryEvent.occurredAt |\n| Detail.deliveryType | ItemResultData.itemResult |\n| Detail.refundAmount | ItemResultData.refundAmount |\n| Detail.rejectReason | ItemResultData.reasonCode |\n| Detail.imgUrl | \u5220\u9664\uFF1B\u56FE\u7247\u6309 eventId \u5355\u72EC\u7ED1\u5B9A |\n\n---\n\n## 11. \u6570\u636E\u5E93\u7EA6\u675F\u4E0E\u8FC1\u79FB\u8981\u6C42\n\nAgent \u5E94\u6839\u636E\u540E\u53F0\u5B9E\u9645 ORM/\u6570\u636E\u5E93\u5B9E\u73B0\u7B49\u4EF7\u7EA6\u675F\uFF0C\u4E0D\u5F3A\u5236\u8868\u540D\uFF0C\u4F46\u5FC5\u987B\u6EE1\u8DB3\uFF1A\n\n\u0060\u0060\u0060text\nUNIQUE(authenticated_device_id, session_id)\nUNIQUE(event_id)                         // \u5168\u5C40\u552F\u4E00\nUNIQUE(session_fk, event_sequence)\nUNIQUE(session_fk, item_id)\nUNIQUE(event_fk) on image attachment     // \u4E00\u4E2A\u4E8B\u4EF6\u6700\u591A\u4E00\u5F20\u56FE\n\u0060\u0060\u0060\n\n\u5EFA\u8BAE\u6301\u4E45\u5316\u8FB9\u754C\uFF1A\n\n- Session\uFF1A\u8BA4\u8BC1\u8BBE\u5907\u3001sessionId\u3001startedAt\u3001e' + N'ndedAt\u3001refundType\u3001userId\u3001\u6D3E\u751F\u6C47\u603B\uFF1B\n- Event\uFF1AeventId\u3001session \u5916\u952E\u3001eventSequence\u3001occurredAt\u3001eventType\uFF1B\n- Event data\uFF1A\u6309\u5B9E\u9645\u6570\u636E\u5E93\u80FD\u529B\u4F7F\u7528\u7C7B\u578B\u5316\u5B50\u8868\u6216\u53EF\u6821\u9A8C JSON\uFF0C\u4F46\u5FC5\u987B\u652F\u6301\u4E0A\u8FF0\u5173\u7CFB\u7EA6\u675F\u548C\u67E5\u8BE2\uFF1B\n- Image\uFF1Aevent \u5916\u952E\u3001\u5B58\u50A8\u5730\u5740\u3001\u5185\u5BB9 hash\u3001\u521B\u5EFA\u65F6\u95F4\u3002\n\n\u8FC1\u79FB\u8981\u6C42\uFF1A\n\n1. \u4F7F\u7528\u6B63\u5F0F migration\uFF0C\u4E0D\u5141\u8BB8\u542F\u52A8\u65F6\u4E34\u65F6\u5EFA\u8868\u6216\u81EA\u52A8\u7834\u574F\u6027\u91CD\u5EFA\uFF1B\n2. \u4E0D\u5220\u9664\u65E7\u6295\u9012\u5386\u53F2\uFF1B\n3. \u65E7\u6570\u636E\u6CA1\u6709\u7A33\u5B9A eventId/eventSequence \u65F6\uFF0C\u4E0D\u5F97\u4F2A\u9020\u6210 V2 \u6570\u636E\uFF1B\n4. \u82E5\u67E5\u8BE2\u9875\u9762\u5FC5\u987B\u540C\u65F6\u5C55\u793A\u65E7/\u65B0\u8BB0\u5F55\uFF0C\u589E\u52A0\u53EA\u8BFB\u6295\u5F71\u6216\u7248\u672C\u5B57\u6BB5\uFF1B\u4E0D\u8981\u8BA9 V2 \u5199\u5165\u7EE7\u7EED\u4F7F\u7528\u65E7 Detail \u6A21\u578B\uFF1B\n5. \u68C0\u67E5\u9000\u6B3E\u3001\u62A5\u8868\u3001\u7528\u6237\u5386\u53F2\u3001\u5BFC\u51FA\u548C\u8FD0\u7EF4\u67E5\u8BE2\uFF0C\u786E\u4FDD\u8BFB\u53D6 V2 \u6D3E\u751F\u5B57\u6BB5\uFF1B\n6. \u8F93\u51FA\u660E\u786E\u7684\u90E8\u7F72\u987A\u5E8F\u3002\u56E0\u4E3A\u65E7\u3001\u65B0 App \u8BF7\u6C42\u4E0D\u517C\u5BB9\uFF0C\u540E\u53F0\u5207\u6362\u5FC5\u987B\u4E0E\u65B0\u7248 App \u53D1\u5E03\u534F\u8C03\u3002\n\n---\n\n## 12. \u5143\u6570\u636E\u5E42\u7B49\u8BED\u4E49\n\n\u552F\u4E00\u8303\u56F4\uFF1A\n\n- sessionId\uFF1A\u8BA4\u8BC1\u8BBE\u5907\u8303\u56F4\u552F\u4E00\uFF1B\n- eventId\uFF1A\u5168\u5C40\u552F\u4E00\uFF1B\n- itemId\uFF1Asession \u8303\u56F4\u552F\u4E00\uFF1B\n- beltReturnId\uFF1Asession \u8303\u56F4\u552F\u4E00\u3002\n\n\u0060SyncDeliveryRecord\u0060 \u884C\u4E3A\uFF1A\n\n1. \u9996\u6B21\' + N'u5408\u6CD5\u8BF7\u6C42\uFF1A\u539F\u5B50\u5199\u5165 session \u548C\u5168\u90E8 events\uFF1B\n2. \u76F8\u540C\u8BBE\u5907\u3001\u76F8\u540C sessionId\u3001\u76F8\u540C\u4E0D\u53EF\u53D8\u4E1A\u52A1\u5185\u5BB9\u91CD\u653E\uFF1A\u8FD4\u56DE\u6210\u529F\uFF0C\u4E0D\u80FD\u65B0\u589E\u7B2C\u4E8C\u4EFD\u8BB0\u5F55\uFF1B\n3. \u76F8\u540C sessionId \u4F46\u4EFB\u4F55\u4E1A\u52A1\u5B57\u6BB5\u6216\u4E8B\u4EF6\u5185\u5BB9\u51B2\u7A81\uFF1A\u8FD4\u56DE\u51B2\u7A81\uFF0C\u4E0D\u80FD\u8986\u76D6\u65E7\u8BB0\u5F55\uFF1B\n4. eventId \u5DF2\u5C5E\u4E8E\u5176\u4ED6 session/device\uFF1A\u8FD4\u56DE\u51B2\u7A81\uFF1B\n5. \u9996\u6B21\u5199\u5165\u4E8B\u52A1\u4E2D\u4EFB\u4E00\u4E8B\u4EF6\u5931\u8D25\uFF1A\u6574\u4F53\u56DE\u6EDA\uFF1B\n6. \u4E0D\u8FD4\u56DE\u9010\u4E8B\u4EF6\u90E8\u5206\u6210\u529F\u7ED3\u679C\u3002\n\n\u53EF\u4EE5\u4F7F\u7528\u89C4\u8303\u5316\u5185\u5BB9 hash \u4F18\u5316\u51B2\u7A81\u5224\u65AD\uFF0C\u4F46 hash \u53EA\u662F\u5B9E\u73B0\u65B9\u5F0F\uFF0C\u4E0D\u80FD\u66FF\u4EE3\u5B57\u6BB5\u7EA7\u4E0D\u53EF\u53D8\u8BED\u4E49\u3002\n\n\u5EFA\u8BAE\u6CBF\u7528\u73B0\u6709 \u0060ApiEnvelope\u0060\uFF0Cdata \u6539\u4E3A\uFF1A\n\n\u0060\u0060\u0060json\n{\n  \u0022sessionId\u0022: \u0022uuid\u0022,\n  \u0022status\u0022: \u0022STORED\u0022\n}\n\u0060\u0060\u0060\n\n\u91CD\u590D\u76F8\u540C\u5185\u5BB9\uFF1A\n\n\u0060\u0060\u0060json\n{\n  \u0022sessionId\u0022: \u0022uuid\u0022,\n  \u0022status\u0022: \u0022ALREADY_STORED\u0022\n}\n\u0060\u0060\u0060\n\n\u4E0D\u5F97\u518D\u8FD4\u56DE\u670D\u52A1\u7AEF Detail UUID \u5217\u8868\u3002\n\n\u9519\u8BEF\u8BED\u4E49\u81F3\u5C11\u533A\u5206\uFF1A\n\n- \u8BF7\u6C42\u5B57\u6BB5/\u679A\u4E3E/\u4E0D\u53D8\u91CF\u9519\u8BEF\uFF1B\n- \u8EAB\u4EFD\u6216\u8BBE\u5907\u5F52\u5C5E\u9519\u8BEF\uFF1B\n- sessionId/eventId \u5185\u5BB9\u51B2\u7A81\uFF1B\n- \u670D\u52A1\u7AEF\u6682\u65F6\u6545\u969C\u3002\n\nHTTP status \u548C\u4E1A\u52A1 error code \u7684\u5177\u4F53\u7EC4\u5408\u6CBF\u7528\u540E\u53F0\u73B0\u6709\u7EDF\u4E00\u89C4\u8303\uFF' + N'0C\u4F46\u51B2\u7A81\u5FC5\u987B\u53EF\u7531\u5BA2\u6237\u7AEF\u8BC6\u522B\u4E3A\u4E0D\u53EF\u91CD\u8BD5\u4E1A\u52A1\u51B2\u7A81\uFF0C\u6682\u65F6\u6545\u969C\u5FC5\u987B\u53EF\u8BC6\u522B\u4E3A\u53EF\u91CD\u8BD5\u3002\n\n---\n\n## 13. \u56FE\u7247\u63A5\u53E3\u8BED\u4E49\n\n\u0060UploadDeliveryRecordImage/{eventId}\u0060 \u5FC5\u987B\uFF1A\n\n1. \u6839\u636E eventId \u67E5\u627E\u5DF2\u6210\u529F\u5199\u5165\u7684\u4E8B\u4EF6\uFF1B\n2. \u9A8C\u8BC1\u4E8B\u4EF6\u5C5E\u4E8E\u5F53\u524D\u8BA4\u8BC1\u8BBE\u5907\uFF1B\n3. \u9A8C\u8BC1 imageAvailability=AVAILABLE\uFF1B\n4. \u5143\u6570\u636E\u4E0D\u5B58\u5728\u65F6\u62D2\u7EDD\u4E0A\u4F20\uFF1B\n5. NONE/MISSING \u65F6\u62D2\u7EDD\u4E0A\u4F20\uFF1B\n6. \u9996\u6B21\u56FE\u7247\u4E0A\u4F20\u6210\u529F\u540E\u7ED1\u5B9A\u5230\u8BE5 eventId\uFF1B\n7. \u76F8\u540C eventId\u3001\u76F8\u540C\u6587\u4EF6\u5185\u5BB9\u91CD\u590D\u4E0A\u4F20\u8FD4\u56DE\u6210\u529F\uFF1B\n8. \u76F8\u540C eventId\u3001\u4E0D\u540C\u6587\u4EF6\u5185\u5BB9\u8FD4\u56DE\u51B2\u7A81\uFF0C\u4E0D\u5141\u8BB8\u9759\u9ED8\u8986\u76D6\uFF1B\n9. \u56FE\u7247\u5B58\u50A8\u548C\u6570\u636E\u5E93\u9644\u4EF6\u8BB0\u5F55\u5FC5\u987B\u907F\u514D\u51FA\u73B0\u201C\u6570\u636E\u5E93\u6210\u529F\u4F46\u6587\u4EF6\u4E0D\u53EF\u5B9A\u4F4D\u201D\u7684\u534A\u5B8C\u6210\u72B6\u6001\uFF1B\u6309\u73B0\u6709\u5BF9\u8C61\u5B58\u50A8\u80FD\u529B\u5B9E\u73B0\u8865\u507F\u6216\u5E42\u7B49\u5199\u5165\uFF1B\n10. \u4E0D\u5141\u8BB8\u901A\u8FC7 eventId \u8BFB\u53D6\u6216\u8986\u76D6\u5176\u4ED6\u8BBE\u5907\u56FE\u7247\u3002\n\n\u5EFA\u8BAE\u54CD\u5E94 data\uFF1A\n\n\u0060\u0060\u0060json\n{\n  \u0022eventId\u0022: \u0022uuid\u0022,\n  \u0022status\u0022: \u0022STORED\u0022\n}\n\u0060\u0060\u0060\n\n\u6216\u91CD\u590D\u76F8\u540C\u56FE\u7247\uFF1A\n\n\u0060\u0060\u0060json\n{\n  \u0022eventId\u0022: \u