sultData.barcode |\n| Detail.deliveryTime | DeliveryEvent.occurredAt |"},{"id":"ba709ac3-083f-4e77-bd2f-09b092ed16a1","documentId":"f81265ad-c319-442c-987c-026bece6f33b","sequence":8,"content":"ACCOUNT \u5FC5\u586B\uFF0C\u5176\u4ED6\u7701\u7565 |\n| Detail.andDeliveryId | \u5220\u9664\uFF1B\u4F7F\u7528 itemId/eventId |\n| Detail.barCode | ItemResultData.barcode |\n| Detail.deliveryTime | DeliveryEvent.occurredAt |\n| Detail.deliveryType | ItemResultData.itemResult |\n| Detail.refundAmount | ItemResultData.refundAmount |\n| Detail.rejectReason | ItemResultData.reasonCode |\n| Detail.imgUrl | \u5220\u9664\uFF1B\u56FE\u7247\u6309 eventId \u' + N'5355\u72EC\u7ED1\u5B9A |\n\n---\n\n## 11. \u6570\u636E\u5E93\u7EA6\u675F\u4E0E\u8FC1\u79FB\u8981\u6C42\n\nAgent \u5E94\u6839\u636E\u540E\u53F0\u5B9E\u9645 ORM/\u6570\u636E\u5E93\u5B9E\u73B0\u7B49\u4EF7\u7EA6\u675F\uFF0C\u4E0D\u5F3A\u5236\u8868\u540D\uFF0C\u4F46\u5FC5\u987B\u6EE1\u8DB3\uFF1A\n\n\u0060\u0060\u0060text\nUNIQUE(authenticated_device_id, session_id)\nUNIQUE(event_id)                         // \u5168\u5C40\u552F\u4E00\nUNIQUE(session_fk, event_sequence)\nUNIQUE(session_fk, item_id)\nUNIQUE(event_fk) on image attachment     // \u4E00\u4E2A\u4E8B\u4EF6\u6700\u591A\u4E00\u5F20\u56FE\n\u0060\u0060\u0060\n\n\u5EFA\u8BAE\u6301\u4E45\u5316\u8FB9\u754C\uFF1A\n\n- Session\uFF1A\u8BA4\u8BC1\u8BBE\u5907\u3001sessionId\u3001startedAt\u3001endedAt\u3001refundType\u3001userId\u3001\u6D3E\u751F\u6C47\u603B\uFF1B\n- Event\uFF1AeventId\u3001session \u5916\u952E\u3001eventSequence\u3001occurredAt\u3001eventType\uFF1B\n- Event data\uFF1A\u6309\u5B9E\u9645\u6570\u636E\u5E93\u80FD\u529B\u4F7F\u7528\u7C7B\u578B\u5316\u5B50\u8868\u6216\u53EF\u6821\u9A8C JSON\uFF0C\u4F46\u5FC5\u987B\u652F\u6301\u4E0A\u8FF0\u5173\u7CFB\u7EA6\u675F\u548C\u67E5\u8BE2\uFF1B\n- Image\uFF1Aevent \u5916\u952E\u3001\u5B58\u50A8\u5730\u5740\u3001\u5185\u5BB9 hash\u3001\u521B\u5EFA\u65F6\u95F4\u3002\n\n\u8FC1\u79FB\u8981\u6C42\uFF1A\n\n1. \u4F7F\u7528\u6B63\u5F0F migration\uFF0C\u4E0D\u5141\u8BB8\u542F\u52A8\u65F6\u4E34\u65F6\u5EFA\u8868\u6216\u81EA\u52A8\u7834\u574F\u6027\u91CD\u5EFA\uFF1B\n2. \u4E0D\u5220\u9664\u65E7\u6295\u9012\u5386\u53F2\uFF1B\n3. \u65E7\u6570\u636E\u6CA1\u6709\u7A33\u5B9A eventId/eventSequence \u65F6\uFF0C\u4E0D\u5F97\u4F2A\u9020\u6210 V2 \u6570\u636E\uFF1B\n4. \u82E5\u67E5\u8BE2\u9875\u9762\u5FC5\u987B\u540C\u65F6\u5C55\u793A\u65E7/\u65B0\u8BB0\u5F55\uFF0C\u589E\u52A0\u53EA\u8BFB\u6295\u5F71\u6216\u7248\u672C\u5B57\u6BB5\uFF1B\u4E0D\u8981\u8BA9 V2 \u5199\u5165\u7EE7\u7EED\u4F7F\u7528\u65E7 Detail \u6A21\u578B\uFF1B\n5. \u68C0\u67E5\u9000\u6B3E\u3001\u62A5\u8868\u3001\u7528\u6237\u5' + N'386\u53F2\u3001\u5BFC\u51FA\u548C\u8FD0\u7EF4\u67E5\u8BE2\uFF0C\u786E\u4FDD\u8BFB\u53D6 V2 \u6D3E\u751F\u5B57\u6BB5\uFF1B\n6. \u8F93\u51FA\u660E\u786E\u7684\u90E8\u7F72\u987A\u5E8F\u3002\u56E0\u4E3A\u65E7\u3001\u65B0 App \u8BF7\u6C42\u4E0D\u517C\u5BB9\uFF0C\u540E\u53F0\u5207\u6362\u5FC5\u987B\u4E0E\u65B0\u7248 App \u53D1\u5E03\u534F\u8C03\u3002\n\n---\n\n## 12. \u5143\u6570\u636E\u5E42\u7B49\u8BED\u4E49\n\n\u552F\u4E00\u8303\u56F4\uFF1A\n\n- sessionId\uFF1A\u8BA4\u8BC1\u8BBE\u5907\u8303\u56F4\u552F\u4E00\uFF1B\n- eventId\uFF1A\u5168\u5C40\u552F\u4E00\uFF1B"},{"id":"41dca50e-0b50-43cc-a0ed-d8ed5de5496b","documentId":"f81265ad-c319-442c-987c-026bece6f33b","sequence":9,"content":"il \u6A21\u578B\uFF1B\n5. \u68C0\u67E5\u9000\u6B3E\u3001\u62A5\u8868\u3001\u7528\u6237\u5386\u53F2\u3001\u5BFC\u51FA\u548C\u8FD0\u7EF4\u67E5\u8BE2\uFF0C\u786E\u4FDD\u8BFB\u53D6 V2 \u6D3E\u751F\u5B57\u6BB5\uFF1B\n6. \u8F93\u51FA\u660E\u786E\u7684\u90E8\u7F72\u987A\u5E8F\u3002\u56E0\u4E3A\u65E7\u3001\u65B0 App \u8BF7\u6C42\u4E0D\u517C\u5BB9\uFF0C\u540E\u53F0\u5207\u6362\u5FC5\u987B\u4E0E\u65B0\u7248 App \u53D1\u5E03\u534F\u8C03\u3002\n\n---\n\n## 12. \u5143\u6570\u636E\u5E42\u7B49\u8BED\u4E49\n\n\u552F\u4E00\u8303\u56F4\uFF1A\n\n- sessionId\uFF1A\u8BA4\u8BC1\u8BBE\u5907\u8303\u56F4\u552F\u4E00\uFF1B\n- eventId\uFF1A\u5168\u5C40\u552F\u4E00\uFF1B\n- itemId\uFF1Asession \u8303\u56F4\u552F\u4E00\uFF1B\n- beltReturnId\uFF1Asession \u8303\u56F4\u552F\u4E00\u3002\n\n\u0060SyncDeliveryRecord\u0060 \u884C\u4E3A\uFF1A\n\n1. \u9996\u6B21\u5408\u6CD5\u8BF7\u6C42\uFF1A\u539F\u5B50\u5199\u5165 session \u548C\u5168\u90E8 events\uFF1B\n2. \u76F8\u540C\u8BBE\u5907\u3001\u76F8\u540C sessionId\u3001\u76F8\u540C\u4E0D\u53EF\u53D8\u4E1A\u52A1\u5185\u5BB9\u91CD\u653E\uFF1A\u8FD4\u56DE\u6210\u529F\uFF0C\u4E0D\u80FD\u65B0\u589E\u7B2C\u4E8C\u4EFD\u8BB0\u5F55\uFF1B\n3. \u76F8\u540C sessionId \u4F46\u4EFB\u4F55\u4E1A\u52A1\u5B57\u6BB5\u6216\u4E8B\u4EF6\u5185\u5BB9\u51B2\u7A81\uFF1A\u8FD4\u56DE\u51B2\u7A81\uFF0C\u4E0D\u80' + N'FD\u8986\u76D6\u65E7\u8BB0\u5F55\uFF1B\n4. eventId \u5DF2\u5C5E\u4E8E\u5176\u4ED6 session/device\uFF1A\u8FD4\u56DE\u51B2\u7A81\uFF1B\n5. \u9996\u6B21\u5199\u5165\u4E8B\u52A1\u4E2D\u4EFB\u4E00\u4E8B\u4EF6\u5931\u8D25\uFF1A\u6574\u4F53\u56DE\u6EDA\uFF1B\n6. \u4E0D\u8FD4\u56DE\u9010\u4E8B\u4EF6\u90E8\u5206\u6210\u529F\u7ED3\u679C\u3002\n\n\u53EF\u4EE5\u4F7F\u7528\u89C4\u8303\u5316\u5185\u5BB9 hash \u4F18\u5316\u51B2\u7A81\u5224\u65AD\uFF0C\u4F46 hash \u53EA\u662F\u5B9E\u73B0\u65B9\u5F0F\uFF0C\u4E0D\u80FD\u66FF\u4EE3\u5B57\u6BB5\u7EA7\u4E0D\u53EF\u53D8\u8BED\u4E49\u3002\n\n\u5EFA\u8BAE\u6CBF\u7528\u73B0\u6709 \u0060ApiEnvelope\u0060\uFF0Cdata \u6539\u4E3A\uFF1A\n\n\u0060\u0060\u0060json\n{\n  \u0022sessionId\u0022: \u0022uuid\u0022,\n  \u0022status\u0022: \u0022STORED\u0022\n}\n\u0060\u0060\u0060\n\n\u91CD\u590D\u76F8\u540C\u5185\u5BB9\uFF1A\n\n\u0060\u0060\u0060json\n{\n  \u0022sessionId\u0022: \u0022uuid\u0022,\n  \u0022status\u0022: \u0022ALREADY_STORED\u0022\n}\n\u0060\u0060\u0060\n\n\u4E0D\u5F97\u518D\u8FD4\u56DE\u670D\u52A1\u7AEF Detail UUID \u5217\u8868\u3002\n\n\u9519\u8BEF\u8BED\u4E49\u81F3\u5C11\u533A\u5206\uFF1A\n\n- \u8BF7\u6C42\u5B57\u6BB5/\u679A\u4E3E/\u4E0D\u53D8\u91CF\u9519\u8BEF\uFF1B\n- \u8EAB\u4EFD\u6216\u8BBE\u5907\u5F52\u5C5E\u9519\u8BEF\uFF1B\n- sessionId/eventId \u5185\u5BB9\u51B2\u7A81\uFF1B\n- \